  `asset_status` varchar(300) DEFAULT NULL,
  `createdbyid` varchar(100) DEFAULT NULL,
  `createdby` varchar(100) DEFAULT NULL,
  `createdon` datetime DEFAULT NULL,
  `updatedbyid` varchar(100) DEFAULT NULL,
  `updatedby` varchar(100) DEFAULT NULL,
  `updatedon` datetime DEFAULT NULL,
  `asset_category` varchar(300) DEFAULT NULL,
  `asset_city` varchar(300) DEFAULT NULL,
  `asset_buildingname` varchar(300) DEFAULT NULL,
  `floor` varchar(45) DEFAULT NULL,
  `bay` varchar(45) DEFAULT NULL,
