CREATE TABLE `AM_MemoryInfo` (
  `Id` int NOT NULL AUTO_INCREMENT,
  `AssetId` varchar(45) DEFAULT NULL,
  `Name` varchar(45) DEFAULT NULL,
  `Manufacturer` varchar(100) DEFAULT NULL,
  `Tag` varchar(100) DEFAULT NULL,
  `SerialNumber` varchar(100) DEFAULT NULL,
  `DeviceLocator` varchar(100) DEFAULT NULL,
  `DataWidth` varchar(45) DEFAULT NULL,
  `BankLabel` varchar(45) DEFAULT NULL,
  `Speed` varchar(45) DEFAULT NULL,
  `Type` varchar(45) DEFAULT NULL,
  `PartNumber` varchar(45) DEFAULT NULL,
  `Model` varchar(45) DEFAULT NULL,
  `PositionRow` varchar(45) DEFAULT NULL,
  `FormFactor` varchar(45) DEFAULT NULL,
  `Capacity` varchar(45) DEFAULT NULL,
  `CapacityInBytes` varchar(45) DEFAULT NULL,
  `IsDisabled` varchar(45) DEFAULT NULL,
  `CreatedBy` varchar(45) DEFAULT NULL,
  `CreatedById` varchar(75) DEFAULT NULL,
  `CreatedOn` datetime DEFAULT NULL,
  `UpdatedBy` varchar(45) DEFAULT NULL,
  `UpdatedById` varchar(45) DEFAULT NULL,
  `UpdatedOn` datetime DEFAULT NULL,
