  `ClockSpeedInGhz` varchar(45) DEFAULT NULL,
  `Manufacturer` varchar(100) DEFAULT NULL,
  `NumberOfCores` varchar(100) DEFAULT NULL,
  `NumberOfEnabledCore` varchar(100) DEFAULT NULL,
  `NumberOfLogicalProcessors` varchar(100) DEFAULT NULL,
  `AddressWidth` varchar(45) DEFAULT NULL,
  `CpuStatus` varchar(45) DEFAULT NULL,
  `SocketDesignation` varchar(45) DEFAULT NULL,
  `IsDisabled` varchar(45) DEFAULT NULL,
  `CreatedBy` varchar(100) DEFAULT NULL,
