  `UpdatedOn` datetime DEFAULT NULL,
  PRIMARY KEY (`Id`)
) ENGINE=InnoDB AUTO_INCREMENT=3988 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

